WITH with_windows AS (SELECT *, ROW_NUMBER() OVER w_recent AS row_seq, RANK() OVER w_grp AS amount_rank, NTILE(3) OVER w_part AS amount_bucket FROM payments WINDOW w_recent AS (ORDER BY amount DESC, id), w_grp AS (ORDER BY amount), w_part AS (PARTITION BY TO_DATE(paid_at), order_id ORDER BY amount, id)) SELECT status, order_id, MIN(row_seq) AS min_row_seq, SORT_ARRAY(COLLECT_SET(status)) AS status_list, SIZE(COLLECT_SET(method)) AS num_methods FROM with_windows GROUP BY 1, 2 ORDER BY status DESC
